 static void RestoreSettingsFiles(Recovery recovery)
 {
  string labGuid=string.IsNullOrEmpty(recovery.labGuid)?AssetDatabase.AssetPathToGUID(Root+"Lab-URP.asset"):recovery.labGuid;if(string.IsNullOrEmpty(labGuid))return;
  foreach(var entry in new[]{("ProjectSettings/GraphicsSettings.asset",recovery.graphicsText,"m_CustomRenderPipeline"),("ProjectSettings/QualitySettings.asset",recovery.qualityText,"customRenderPipeline")})
  {
   if(string.IsNullOrEmpty(entry.Item2)||!File.Exists(entry.Item1))continue;
   string current=File.ReadAllText(entry.Item1);string pattern=@"(?m)^ *"+entry.Item3+@": \{[^\r\n]*\}";var originals=System.Text.RegularExpressions.Regex.Matches(entry.Item2,pattern);int index=0;
   string restored=System.Text.RegularExpressions.Regex.Replace(current,pattern,match=>{int i=index++;return match.Value.Contains(labGuid)&&i<originals.Count?originals[i].Value:match.Value;});
   // Only this lab's pipeline pointers are restored. Other concurrent settings edits survive.
   if(restored!=current)File.WriteAllText(entry.Item1,restored);
  }
 }
