 static int ActiveLod(){var group=subject.GetComponentInChildren<LODGroup>();if(!group)return -1;if(forcedLod>=0)return forcedLod;float scale=Mathf.Max(group.transform.lossyScale.x,group.transform.lossyScale.y,group.transform.lossyScale.z);float height=group.size*scale*QualitySettings.lodBias/(camera.orthographic?camera.orthographicSize*2:Mathf.Max(.01f,Vector3.Distance(camera.transform.position,group.transform.TransformPoint(group.localReferencePoint)))*2*Mathf.Tan(camera.fieldOfView*.5f*Mathf.Deg2Rad));var lods=group.GetLODs();for(int i=0;i<lods.Length;i++)if(height>=lods[i].screenRelativeTransitionHeight)return i;return lods.Length;}
