 static void SetCamera(Camera c,int view)
 {
  if(!c)return;c.aspect=(float)s.width/s.height;
  var b=subject?BoundsOf(subject):new Bounds(new Vector3(0,7,0),new Vector3(8,14.3f,20));Vector3 focus=b.center;float pitch=35.26439f,yaw=view==1?35:325,dist=80;float size=Mathf.Max(b.size.y,b.size.z*.72f)*.82f;c.orthographic=true;
  if(view==0){pitch=0;yaw=0;size=b.size.y*.58f;}
  if(view==3){c.orthographic=false;c.fieldOfView=55;c.transform.position=new Vector3(9,1.7f,-24);c.transform.LookAt(new Vector3(0,6,-7));return;}
  if(view==4){focus=new Vector3(3.1f,6.42f,-6.85f);pitch=12;yaw=15;size=1.9f;}
  if(view==5){focus=new Vector3(.3f,12.7f,-7.1f);pitch=25;yaw=325;size=3.8f;}
  if(view==12){focus=new Vector3(12,1.2f,2);pitch=15;yaw=0;size=5;}
  if(view==13){focus=new Vector3(-12,6,0);pitch=35.26439f;yaw=0;size=20;}
  if(view==14){yaw=145;pitch=35.26439f;}if(view==15){yaw=215;pitch=35.26439f;}if(view==16){yaw=145;pitch=70;size=12;}
  if((view==4||view==5)&&!SubjectMeshes().Any(m=>m.name.StartsWith("Bowfront-"))){focus=b.center+Vector3.up*b.size.y*(view==4?.08f:.4f);pitch=view==4?20:30;yaw=325;size=Mathf.Max(.4f,b.size.magnitude*.22f);}
  if(view>=6&&view<=11){int level=view-6;float halfWidth=s.gameplaySide*.5f*Mathf.Sqrt(2);float halfHeight=halfWidth*Mathf.Sin(pitch*Mathf.Deg2Rad)+s.gameplayRelief*.5f*Mathf.Cos(pitch*Mathf.Deg2Rad);float farthest=1.12f*Mathf.Max(halfHeight,halfWidth/c.aspect);size=farthest/Mathf.Pow(2,5-level)/(level<=1?1.25f:1)*(level<=2?.5f:1);if(level>=3)size*=.5f;if(level==5)size*=.9025f;yaw=315;dist=Mathf.Max(s.gameplaySide*1.6f,s.gameplayRelief*2+200);}
