 static void Diagnostics(bool useOverride)
 {
  if(diagnosticBase==null){diagnosticBase=subject.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct().ToArray();diagnosticLive=diagnosticBase.Select(m=>Object.Instantiate(m)).ToArray();var map=diagnosticBase.Select((m,i)=>(m,i)).ToDictionary(p=>p.m,p=>diagnosticLive[p.i]);foreach(var r in subject.GetComponentsInChildren<Renderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>map[m]).ToArray();}
  for(int i=0;i<diagnosticLive.Length;i++){var m=diagnosticLive[i];m.CopyPropertiesFromMaterial(diagnosticBase[i]);if(!s.normals)m.DisableKeyword("_NORMALMAP");if(m.HasProperty("_BumpScale"))m.SetFloat("_BumpScale",diagnosticBase[i].GetFloat("_BumpScale")*s.normalStrength);if(useOverride){if(m.HasProperty("_Smoothness"))m.SetFloat("_Smoothness",s.smoothness);if(m.HasProperty("_Metallic"))m.SetFloat("_Metallic",s.metallic);if(m.HasProperty("_MetallicGlossMap")){m.SetTexture("_MetallicGlossMap",null);m.DisableKeyword("_METALLICSPECGLOSSMAP");}if(m.HasProperty("_OcclusionStrength"))m.SetFloat("_OcclusionStrength",s.occlusion);}}Apply();
 }
 public static void Audit()
 {
  Directory.CreateDirectory(Output);var lines=new List<string>{"Architectural Rendering Lab native import audit",DateTime.UtcNow.ToString("O"),"Active color space: "+QualitySettings.activeColorSpace};
  foreach(var m in SubjectMeshes()){lines.Add($"MESH {m.name}: {m.triangles.Length/3} triangles; normals {m.normals.Length}/{m.vertexCount}; tangents {m.tangents.Length}/{m.vertexCount}; bounds {m.bounds}");}
  foreach(var m in subject.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct()){
   lines.Add("MATERIAL "+m.name+" shader="+m.shader.name+" smoothness="+(m.HasProperty("_Smoothness")?m.GetFloat("_Smoothness"):0));foreach(string key in new[]{"_BaseMap","_BumpMap","_MetallicGlossMap","_OcclusionMap","_EmissionMap"}){if(!m.HasProperty(key))continue;var tex=m.GetTexture(key);if(!tex){lines.Add("  "+key+": absent (not synthesized)");continue;}var path=AssetDatabase.GetAssetPath(tex);var ti=AssetImporter.GetAtPath(path) as TextureImporter;lines.Add($"  {key}: {path}; {tex.width}x{tex.height}; mipCount={(tex as Texture2D)?.mipmapCount}; sRGB={ti?.sRGBTexture}; type={ti?.textureType}; compression={ti?.textureCompression}; mipmaps={ti?.mipmapEnabled}");}}
  lines.Add("MetallicGloss packed R=metallic, A=1-roughness; textures linear. Albedo sRGB. No generic normals substituted where source absent.");File.WriteAllLines(Output+"/Material-Import-Audit.txt",lines);
 }
 static string MaterialFingerprint(){var lines=new List<string>();foreach(var m in subject.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct()){lines.Add(m.shader.name+":"+string.Join(",",m.shaderKeywords.OrderBy(k=>k)));foreach(var key in new[]{"_BaseColor","_EmissionColor"})if(m.HasProperty(key))lines.Add(key+":"+m.GetColor(key));foreach(var key in new[]{"_BumpScale","_Smoothness","_Metallic","_OcclusionStrength"})if(m.HasProperty(key))lines.Add(key+":"+m.GetFloat(key));foreach(var key in new[]{"_BaseMap","_BumpMap","_MetallicGlossMap","_OcclusionMap","_EmissionMap"})if(m.HasProperty(key))lines.Add(key+":"+AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(m.GetTexture(key))));}return Hash128.Compute(string.Join("|",lines)).ToString();}
 static string Fingerprint(){var text=string.Join("|",SubjectMeshes().Select(m=>AssetDatabase.GetAssetDependencyHash(AssetDatabase.GetAssetPath(m)).ToString()));return Hash128.Compute(text).ToString();}
 static void Render(Camera c,RenderTexture rt){RenderPipeline.SubmitRenderRequest(c,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});}
 static void Capture(string label)
 {
  camera=GameObject.Find(Views[s.view]+" Camera").GetComponent<Camera>();SetCamera(camera,s.view);Directory.CreateDirectory(Output);var rt=new RenderTexture(s.width,s.height,24,RenderTextureFormat.ARGBHalf,RenderTextureReadWrite.Linear);rt.Create();var active=RenderTexture.active;var watch=System.Diagnostics.Stopwatch.StartNew();Render(camera,rt);RenderTexture.active=rt;var image=new Texture2D(s.width,s.height,TextureFormat.RGBAFloat,false,true);image.ReadPixels(new Rect(0,0,s.width,s.height),0,0);image.Apply();watch.Stop();previewMs=watch.Elapsed.TotalMilliseconds;var pixels=image.GetPixels();if(QualitySettings.activeColorSpace==ColorSpace.Linear)for(int i=0;i<pixels.Length;i++)pixels[i]=pixels[i].gamma;var png=new Texture2D(s.width,s.height,TextureFormat.RGB24,false);png.SetPixels(pixels);png.Apply();string name=label.Replace(" ","-")+"__"+Views[s.view]+"__"+QualitySettings.activeColorSpace+"__"+s.width+"x"+s.height;File.WriteAllBytes(Output+"/"+name+".png",png.EncodeToPNG());File.WriteAllText(Output+"/"+name+".json",JsonUtility.ToJson(s,true)+"\n");File.WriteAllText(Output+"/"+name+".evidence.txt","Geometry dependency hash: "+Fingerprint()+"\nMaterial state hash (source properties; lighting emission blocks excluded): "+MaterialFingerprint()+"\nCamera "+camera.transform.position+" rotation "+camera.transform.eulerAngles+" ortho "+camera.orthographicSize+"\nCPU submit + sync capture milliseconds: "+previewMs+" (not gameplay FPS)\n");Object.DestroyImmediate(image);Object.DestroyImmediate(png);RenderTexture.active=active;rt.Release();Object.DestroyImmediate(rt);
 }
 public static void Compare()
 {
  if(capturing)return;restorePreset=s.preset;restoreView=s.view;jobs.Clear();foreach(int p in (batch?new[]{0,5}:Enumerable.Range(0,7)))foreach(int v in (batch?new[]{0,2,4}:new[]{0,1,2,3,4,5})){int pp=p,vv=v;jobs.Add(()=>{s.view=vv;ApplyPreset(pp);});jobs.Add(()=>Capture(Presets[pp]));}
  jobs.Add(()=>{s.view=2;ApplyPreset(5);});jobs.Add(()=>Capture("Current-In-Game-Control"));jobs.Add(()=>{s.ao=false;Apply();});jobs.Add(()=>Capture("Current-In-Game-Only-AO-Off"));jobs.Add(()=>{ApplyPreset(5);s.exposure=0;Apply();});jobs.Add(()=>Capture("Current-In-Game-Only-Exposure-Zero"));jobs.Add(()=>{ApplyPreset(5);s.normals=false;Diagnostics(false);});jobs.Add(()=>Capture("Current-In-Game-Only-Normals-Off"));if(!batch){jobs.Add(()=>{s.normals=true;Diagnostics(false);s.view=12;ApplyPreset(0);});jobs.Add(()=>Capture("Calibration-Reflection-On"));jobs.Add(()=>{s.reflection=0;Apply();});jobs.Add(()=>Capture("Calibration-Only-Reflection-Zero"));}
  jobs.Add(()=>{s.normals=true;Diagnostics(false);ApplyPreset(restorePreset);s.view=restoreView;Apply();Audit();});job=0;frame=0;capturing=true;
 }
