 static void Tick()
 {
  if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;
  try{
   string request="Library/ArchitecturalRenderingLab.request";if(File.Exists(request)){var command=File.ReadAllText(request).Trim();File.Delete(request);if(command=="build")Build();else if(command=="capture"){Bind();Compare();}else if(command=="audit"){Bind();Audit();}else if(command=="open"){EditorSceneManager.OpenScene(ScenePath);Bind();ApplyPreset(s.preset);Open();}else if(command=="export")ExportIsolated();else if(command=="restore"){Restore();pausedSession=true;}else if(command=="support-cameras")SupportCameras();else if(command=="extra-captures")ExtraCaptures();else if(command=="night-captures")NightCaptures();else if(command=="finalize-layout")FinalizeLayout();else if(command=="validate-loader")ValidateLoader();}
   if(!InLab){if(scoped)Restore();return;}if(!sun&&!pausedSession)Bind();
   double now=EditorApplication.timeSinceStartup;if(lastFrame>0)editorFps=Mathf.Lerp(editorFps,(float)(1/Math.Max(.001,now-lastFrame)),.1f);lastFrame=now;
   if(capturing&&++frame>=6){frame=0;if(job<jobs.Count){jobs[job++]();EditorApplication.QueuePlayerLoopUpdate();}else{capturing=false;File.WriteAllText(Output+"/Capture-Complete.txt",DateTime.UtcNow.ToString("O"));if(batch){Restore();EditorApplication.Exit(0);}}}
  }catch(Exception e){capturing=false;Directory.CreateDirectory(Output);File.WriteAllText(Output+"/Error.txt",e.ToString());Debug.LogException(e);if(batch)EditorApplication.Exit(1);}
 }
